import socket
s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM); s.settimeout(1)
for d in (b'{"op":"list"}', b'[1,2]', b'x' * 1300):
    s.sendto(d, ('127.0.0.1', 9453))
    try: print(f'[thử] Gửi {len(d)} byte -> nhận {len(s.recv(65535))} byte')
    except TimeoutError: print(f'[thử] Gửi {len(d)} byte -> không có phản hồi sau 1 s')
